    const rx = -fz;
    const rz = fx;
    const along = (pos) => (pos[0] - cx) * rx + (pos[2] - cz) * rz;
    const away = (pos) => (pos[0] - cx) * fx + (pos[2] - cz) * fz;
    const rows = points.slice().sort((a, b) => away(b.position) - away(a.position));
