// =====================================================================================
// Go - scene script for the "Scripted" variants of the Go game pack.
//
// ONE source for three boards. `compile.ts --write <dir>` stamps out go-9x9.ts,
// go-13x13.ts and go-19x19.ts from this file by rewriting the GO_N line below; each is attached
// to its own Scripted variant. The board size has to be a constant: the rules kernel is cut out
// of the script by name and must be pure, so it cannot ask the table which variant is playing.
//
// Runs on the host only. The table is the game:
// - People play by taking a stone from their bowl and putting it on an empty point. The script
//   checks it is the right colour, the right player and a legal move (not suicide, not a ko
//   recapture), then takes the captured stones off the board. A stone that is not a legal move
//   is left where it is with a notice; it does not count until it is taken back.
// - Right-click the board for Pass, Resign, New game and Estimate the score.
// - Two passes in a row end the game. It is scored by AREA (stones plus surrounded points, as
//   in Chinese rules) with komi for White. Stones still on the board count as alive, except
//   stones sitting inside territory that is alive beyond any doubt (Benson's pass-alive test),
//   which count for its owner. So capture what is dead before you pass.
// - Simple ko. Suicide is not allowed. A game that reaches GO_MAX_PLIES moves is scored as it
//   stands.
// - Bots place stones from the bowls. With turn mode on, the table calls a bot's turn; with it
//   off (every solo table) the script moves its seated bots itself.
// - Every game is a match (`match`) with this kernel: every move is recorded, the result is the
//   kernel's score, and in a ranked match a hand edit to the board is put back.
//
// The AI bot runs KataGo networks (g170 run, public domain/CC0; https://katagotraining.org),
// converted to this platform's model format. The kernel's `encode` is KataGo's own "V7" input
// encoding (cpp/neuralnet/nninputs.cpp, MIT licence, (c) David J Wu and contributors), ported
// here feature by feature, so the networks see exactly the planes they were trained on.
// =====================================================================================

// =====================================================================================
// Rules kernel. Everything from here to the end of `kernel` is pure: no world, no table,
// no clock, no random numbers. Names are prefixed GO_ / go so nothing below shares a name
// with them (the training tools match names, they do not resolve them).
// =====================================================================================

/** The board size. `compile.ts` rewrites this one line per variant. */
const GO_N = 19;
const GO_AREA = GO_N * GO_N;
/** The pass move and its policy slot. */
const GO_PASS = GO_AREA;
const GO_KOMI = 7.5;
/** A game this long is scored as it stands (simple ko allows cycles). */
const GO_MAX_PLIES = GO_AREA * 3;
/** KataGo's input: 22 spatial planes, then its 19 global inputs as constant planes. */
const GO_SPATIAL = 22;
const GO_GLOBAL = 19;
const GO_PLANES = GO_SPATIAL + GO_GLOBAL;
/** KataGo's ladder search gives up (answers "no ladder") after this many moves. */
const GO_LADDER_BUDGET = 25000;
const GO_LADDER_STACK = Math.floor((GO_AREA * 3) / 2) + 1;

interface GoState {
  /** GO_AREA points, y * GO_N + x (y = 0 is the far row from Black): 0 empty, 1 black, -1 white. */
  board: number[];
  /** The seat to move: "black" or "white". */
  toPlay: string;
  /** [black, white]. */
  seats: [string, string];
  /** The point the side to move may not play (simple ko), or -1. */
  ko: number;
  /** Passes in a row just before this position. */
  passes: number;
  /** Moves played so far (passes included). */
  ply: number;
  /** The last moves, oldest first, at most five (GO_PASS for a pass). */
  recent: number[];
  /** The board one and two moves ago (null before there were that many moves), and their ko points. */
  prev1: number[] | null;
  prev1Ko: number;
  prev2: number[] | null;
  prev2Ko: number;
  /** Stones each side has captured: [by black, by white]. */
  caps: [number, number];
}

/** A point 0..GO_AREA-1, or GO_PASS. */
type GoMove = number;

/** Neighbours of each point in KataGo's order: up, left, right, down. */
const GO_ADJ: number[][] = goBuildAdjacency();

function goBuildAdjacency(): number[][] {
  const all: number[][] = [];
  for (let p = 0; p < GO_AREA; p += 1) {
    const x = p % GO_N;
    const y = Math.floor(p / GO_N);
    const list: number[] = [];
    if (y > 0) list.push(p - GO_N);
    if (x > 0) list.push(p - 1);
    if (x < GO_N - 1) list.push(p + 1);
    if (y < GO_N - 1) list.push(p + GO_N);
    all.push(list);
  }
  return all;
}

function goAdjacent(a: number, b: number): boolean {
  return GO_ADJ[a].indexOf(b) >= 0;
}

/** The chain through `p` and its liberties (both in search order). `b[p]` must be a stone. */
function goChain(b: ArrayLike<number>, p: number): { stones: number[]; libs: number[] } {
  const colour = b[p];
  const stones: number[] = [p];
  const libs: number[] = [];
  const seen = new Uint8Array(GO_AREA);
  seen[p] = 1;
  for (let i = 0; i < stones.length; i += 1) {
    for (const q of GO_ADJ[stones[i]]) {
      if (seen[q]) continue;
      if (b[q] === colour) {
        seen[q] = 1;
        stones.push(q);
      } else if (b[q] === 0) {
        seen[q] = 1;
        libs.push(q);
      }
    }
  }
  return { stones, libs };
}

function goLibertyCount(b: ArrayLike<number>, p: number): number {
  return goChain(b, p).libs.length;
}

/** Chain ids (one number per chain, -1 for empty points) and each chain's liberty count. */
function goChains(b: ArrayLike<number>): { id: Int32Array; libs: number[]; size: number[] } {
  const id = new Int32Array(GO_AREA).fill(-1);
  const libs: number[] = [];
  const size: number[] = [];
  for (let p = 0; p < GO_AREA; p += 1) {
    if (b[p] === 0 || id[p] >= 0) continue;
    const chain = goChain(b, p);
    const index = libs.length;
    for (const s of chain.stones) id[s] = index;
    libs.push(chain.libs.length);
    size.push(chain.stones.length);
  }
  return { id, libs, size };
}

/** Immediate empty neighbours. */
function goImmediateLibs(b: ArrayLike<number>, p: number): number {
  let count = 0;
  for (const q of GO_ADJ[p]) if (b[q] === 0) count += 1;
  return count;
}

/**
 * Whether `colour` may play on `p` with ko point `ko`: empty, not the ko point, and not suicide
 * (a stone with no liberty that captures nothing).
 */
function goLegal(b: ArrayLike<number>, ko: number, p: number, colour: number): boolean {
  if (p === GO_PASS) return true;
  if (p < 0 || p >= GO_AREA || b[p] !== 0 || p === ko) return false;
  for (const q of GO_ADJ[p]) {
    if (b[q] === 0) return true;
    const libs = goLibertyCount(b, q);
    if (b[q] === colour && libs > 1) return true;
    if (b[q] === -colour && libs === 1) return true;
  }
  return false;
}

/**
 * Play `p` for `colour` on a copy of `b`. Returns the new board, the ko point it leaves (KataGo's
 * rule: exactly one stone captured by a lone stone that now has one liberty) and the captured
 * points. Assumes the move is legal.
 */
function goPlay(b: ArrayLike<number>, p: number, colour: number): { board: number[]; ko: number; captured: number[] } {
  const next: number[] = [];
  for (let i = 0; i < GO_AREA; i += 1) next.push(b[i]);
  if (p === GO_PASS) return { board: next, ko: -1, captured: [] };
  next[p] = colour;
  const captured: number[] = [];
  let lastCapture = -1;
  for (const q of GO_ADJ[p]) {
    if (next[q] !== -colour) continue;
    const chain = goChain(next, q);
    if (chain.libs.length > 0) continue;
    for (const s of chain.stones) {
      next[s] = 0;
      captured.push(s);
    }
    lastCapture = q;
  }
  let ko = -1;
  if (captured.length === 1) {
    const own = goChain(next, p);
    if (own.stones.length === 1 && own.libs.length === 1) ko = lastCapture;
  }
  return { board: next, ko, captured };
}

/** Liberties of a stone `colour` would place on `p`, captures counted in, capped at `max`. */
function goLibsAfterPlay(b: ArrayLike<number>, p: number, colour: number, max: number): number {
  const played = goPlay(b, p, colour);
  return Math.min(max, goChain(played.board, p).libs.length);
}

/** KataGo's `wouldBeKoCapture`: `colour` playing `p` would capture exactly one lone stone, surrounded. */
function goWouldBeKoCapture(b: ArrayLike<number>, p: number, colour: number): boolean {
  if (b[p] !== 0) return false;
  let capturable = -1;
  for (const q of GO_ADJ[p]) {
    if (b[q] !== -colour) return false;
    if (goLibertyCount(b, q) === 1) {
      if (capturable >= 0) return false;
      capturable = q;
    }
  }
  return capturable >= 0 && goChain(b, capturable).stones.length === 1;
}

/** Liberties of the opponent chains in atari next to the chain through `p` (the moves that capture them). */
function goCapturesFor(b: ArrayLike<number>, p: number): number[] {
  const colour = b[p];
  const out: number[] = [];
  const doneChains: number[] = [];
  for (const s of goChain(b, p).stones) {
    for (const q of GO_ADJ[s]) {
      if (b[q] !== -colour) continue;
      const enemy = goChain(b, q);
      if (enemy.libs.length !== 1) continue;
      let key = enemy.stones[0];
      for (const s2 of enemy.stones) if (s2 < key) key = s2;
      if (doneChains.indexOf(key) >= 0) continue;
      doneChains.push(key);
      if (out.indexOf(enemy.libs[0]) < 0) out.push(enemy.libs[0]);
    }
  }
  return out;
}

/** KataGo's `countHeuristicConnectionLibertiesX2`, to order an attacker's two tries. */
function goConnectionLibsX2(b: ArrayLike<number>, p: number, colour: number): number {
  let total = 0;
  for (const q of GO_ADJ[p]) {
    if (b[q] !== colour) continue;
    const libs = goLibertyCount(b, q);
    if (libs > 1) total += libs * 2 - 3;
  }
  return total;
}

interface GoLadderBudget {
  nodes: number;
  aborted: boolean;
}

/**
 * KataGo's `searchIsLadderCaptured`, as a recursion: can the chain through `loc` (the defender) be
 * captured by a ladder - the attacker always leaving it one liberty - when `defenderFirst` says
 * who moves now? Same base cases, move lists, double-ko rule, stack limit and node budget.
 */
function goLadderSearch(b: number[], ko: number, loc: number, pla: number, depth: number, defenderFirst: boolean, budget: GoLadderBudget): boolean {
  if (budget.aborted) return false;
  if (depth >= GO_LADDER_STACK - 1) return true;
  if (budget.nodes >= GO_LADDER_BUDGET) {
    budget.aborted = true;
    return false;
  }
  const isDefender = defenderFirst ? depth % 2 === 0 : depth % 2 === 1;
  const chain = goChain(b, loc);
  const libs = chain.libs.length;
  if (!isDefender && libs <= 1) return true;
  if (!isDefender && libs >= 3) return false;
  if (isDefender && libs >= 2) return false;
  if (isDefender && ko >= 0) return false;

  let moves: number[];
  if (isDefender) {
    moves = goCapturesFor(b, loc);
    const lone = chain.libs[0];
    if (moves.indexOf(lone) < 0) moves.push(lone);
    const after = goLibsAfterPlay(b, lone, pla, 3);
    if (after >= 3) return false;
    if (moves.length === 1 && after <= 1) return true;
  } else {
    moves = [chain.libs[0], chain.libs[1]];
    let libs0 = goImmediateLibs(b, moves[0]);
    let libs1 = goImmediateLibs(b, moves[1]);
    if (libs0 === 0 && libs1 === 0 && goWouldBeKoCapture(b, moves[0], -pla) && goWouldBeKoCapture(b, moves[1], -pla)) {
      if (goLibsAfterPlay(b, moves[0], pla, 3) <= 2 && goLibsAfterPlay(b, moves[1], pla, 3) <= 2 && goCapturesFor(b, loc).length === 0) {
        return true;
      }
    }
    if (!goAdjacent(moves[0], moves[1])) {
      if (libs0 >= 3 && libs1 >= 3) return false;
      if (libs0 >= 3) moves = [moves[0]];
      else if (libs1 >= 3) moves = [moves[1]];
    }
    if (moves.length > 1) {
      libs0 = libs0 * 2 + goConnectionLibsX2(b, moves[0], pla);
      libs1 = libs1 * 2 + goConnectionLibsX2(b, moves[1], pla);
      if (libs1 > libs0) moves = [moves[1], moves[0]];
    }
  }

  const mover = isDefender ? pla : -pla;
  for (const move of moves) {
    if (!goLegal(b, ko, move, mover)) continue;
    budget.nodes += 1;
    const played = goPlay(b, move, mover);
    const captured = goLadderSearch(played.board, played.ko, loc, pla, depth + 1, defenderFirst, budget);
    if (budget.aborted) return false;
    if (isDefender && !captured) return false;
    if (!isDefender && captured) return true;
  }
  return isDefender;
}

/** A chain with one liberty, defender to move: is it caught in a ladder? (ko assumed to work for the defender). */
function goLadderCaptured(b: number[], loc: number): boolean {
  const budget: GoLadderBudget = { nodes: 0, aborted: false };
  const result = goLadderSearch(b, -1, loc, b[loc], 0, true, budget);
  return budget.aborted ? false : result;
}

/** A chain with two liberties: the attacker's first moves that start a working ladder. */
function goLadderWorkingMoves(b: number[], ko: number, loc: number): number[] {
  const pla = b[loc];
  const libs = goChain(b, loc).libs;
  const working: number[] = [];
  for (const move of libs.slice(0, 2)) {
    if (!goLegal(b, ko, move, -pla)) continue;
    const played = goPlay(b, move, -pla);
    if (goLadderCaptured(played.board, loc)) working.push(move);
  }
  return working;
}

/**
 * KataGo's `iterLadders`: every stone of a chain with one or two liberties that a ladder
 * captures, and - for a two-liberty chain - the attacker moves that do it.
 */
function goLadders(b: number[], ko: number): { laddered: number[]; working: { chain: number[]; moves: number[] }[] } {
  const laddered: number[] = [];
  const working: { chain: number[]; moves: number[] }[] = [];
  const solved = new Int8Array(GO_AREA);
  for (let p = 0; p < GO_AREA; p += 1) {
    if (b[p] === 0 || solved[p]) continue;
    const chain = goChain(b, p);
    for (const s of chain.stones) solved[s] = 1;
    const libs = chain.libs.length;
    if (libs !== 1 && libs !== 2) continue;
    let caught = false;
    let moves: number[] = [];
    if (libs === 1) {
      caught = goLadderCaptured(b, p);
    } else {
      moves = goLadderWorkingMoves(b, ko, p);
      caught = moves.length > 0;
    }
    if (!caught) continue;
    for (const s of chain.stones) laddered.push(s);
    if (libs === 2) working.push({ chain: chain.stones, moves });
  }
  return { laddered, working };
}

/**
 * KataGo's `calculateAreaForPla` (Benson's algorithm): mark `colour`'s pass-alive chains and the
 * regions they own in `result`, plus (unsafeBig) empty regions only `colour` borders. Suicide is
 * illegal here, so only empty points decide which chains a region is vital for.
 */
function goAreaFor(b: ArrayLike<number>, colour: number, chains: { id: Int32Array }, result: number[]): void {
  const regionOf = new Int32Array(GO_AREA).fill(-1);
  const regions: { points: number[]; vital: number[]; internal: number; containsOpp: boolean }[] = [];
  let anyOwn = false;
  for (let p = 0; p < GO_AREA; p += 1) {
    if (b[p] === colour) anyOwn = true;
    if (regionOf[p] >= 0 || b[p] !== 0) continue;
    const index = regions.length;
    const vital: number[] = [];
    for (const q of GO_ADJ[p]) {
      if (b[q] === colour && vital.indexOf(chains.id[q]) < 0) vital.push(chains.id[q]);
    }
    const region = { points: [p], vital, internal: 0, containsOpp: false };
    regionOf[p] = index;
    for (let i = 0; i < region.points.length; i += 1) {
      const at = region.points[i];
      if (b[at] === 0 && region.vital.length > 0) {
        region.vital = region.vital.filter((chainId) => GO_ADJ[at].some((q) => b[q] === colour && chains.id[q] === chainId));
      }
      if (region.internal < 2 && !GO_ADJ[at].some((q) => b[q] === colour)) region.internal += 1;
      if (b[at] === -colour) region.containsOpp = true;
      for (const q of GO_ADJ[at]) {
        if ((b[q] === 0 || b[q] === -colour) && regionOf[q] < 0) {
          regionOf[q] = index;
          region.points.push(q);
        }
      }
    }
    regions.push(region);
  }

  // Own chains and how many regions are vital to each.
  const ownChains: number[] = [];
  const stonesOf = new Map<number, number[]>();
  for (let p = 0; p < GO_AREA; p += 1) {
    if (b[p] !== colour) continue;
    const id = chains.id[p];
    let list = stonesOf.get(id);
    if (!list) {
      list = [];
      stonesOf.set(id, list);
      ownChains.push(id);
    }
    list.push(p);
  }
  const vitalCount = new Map<number, number>();
  for (const id of ownChains) vitalCount.set(id, 0);
  for (const region of regions) for (const id of region.vital) vitalCount.set(id, (vitalCount.get(id) ?? 0) + 1);

  const killed = new Set<number>();
  const regionBordersDead = new Uint8Array(regions.length);
  for (;;) {
    let killedAny = false;
    for (const id of ownChains) {
      if (killed.has(id) || (vitalCount.get(id) ?? 0) >= 2) continue;
      killed.add(id);
      killedAny = true;
      for (const s of stonesOf.get(id) ?? []) {
        for (const q of GO_ADJ[s]) {
          const r = regionOf[q];
          if (r < 0 || regionBordersDead[r]) continue;
          regionBordersDead[r] = 1;
          for (const vid of regions[r].vital) vitalCount.set(vid, (vitalCount.get(vid) ?? 0) - 1);
        }
      }
    }
    if (!killedAny) break;
  }

  for (const id of ownChains) {
    if (killed.has(id)) continue;
    for (const s of stonesOf.get(id) ?? []) result[s] = colour;
  }
  regions.forEach((region, r) => {
    const passAliveTerritory = region.internal <= 1 && !regionBordersDead[r] && anyOwn;
    const safeBig = !region.containsOpp && !regionBordersDead[r] && anyOwn;
    if (passAliveTerritory || safeBig) {
      for (const p of region.points) result[p] = colour;
    } else if (!region.containsOpp && anyOwn) {
      for (const p of region.points) if (result[p] === 0) result[p] = colour;
    }
  });
}

/**
 * KataGo's `calculateArea(nonPassAliveStones, safeBigTerritories, unsafeBigTerritories)` with
 * every flag on: the owner of every point for scoring (0 = nobody). The same map is the
 * network's area input and the final count.
 */
function goArea(b: ArrayLike<number>): number[] {
  const result: number[] = [];
  for (let p = 0; p < GO_AREA; p += 1) result.push(0);
  const chains = goChains(b);
  goAreaFor(b, 1, chains, result);
  goAreaFor(b, -1, chains, result);
  for (let p = 0; p < GO_AREA; p += 1) if (result[p] === 0) result[p] = b[p];
  return result;
}

/** Area points: black, white. */
function goAreaCount(b: ArrayLike<number>): { black: number; white: number } {
  let black = 0;
  let white = 0;
  for (const owner of goArea(b)) {
    if (owner === 1) black += 1;
    else if (owner === -1) white += 1;
  }
  return { black, white };
}

/** Black's area minus White's area minus komi: above 0 Black wins. */
function goMargin(b: ArrayLike<number>): number {
  const count = goAreaCount(b);
  return count.black - count.white - GO_KOMI;
}

function goColourToMove(s: GoState): number {
  return s.toPlay === s.seats[0] ? 1 : -1;
}

function goIsOver(s: GoState): boolean {
  return s.passes >= 2 || s.ply >= GO_MAX_PLIES;
}

/** The KataGo komi parity wave (global input 18) for the side to move's komi. */
function goKomiWave(selfKomi: number): number {
  // Every board here has an odd number of points, so the drawable komis are odd.
  const floor = Math.floor((selfKomi - 1) / 2) * 2 + 1;
  let delta = selfKomi - floor;
  if (delta < 0) delta = 0;
  if (delta > 2) delta = 2;
  return delta < 0.5 ? delta : delta < 1.5 ? 1 - delta : delta - 2;
}

const kernel: RulesKernel<GoState, GoMove> = {
  id: "go-" + String(GO_N),
  version: 1,

  initial(seatList) {
    if (seatList.length !== 2 || seatList[0] === seatList[1]) {
      throw new Error("Go needs exactly two different seats: [black, white].");
    }
    const board: number[] = [];
    for (let p = 0; p < GO_AREA; p += 1) board.push(0);
    return {
      board,
      toPlay: seatList[0],
      seats: [seatList[0], seatList[1]],
      ko: -1,
      passes: 0,
      ply: 0,
      recent: [],
      prev1: null,
      prev1Ko: -1,
      prev2: null,
      prev2Ko: -1,
      caps: [0, 0]
    };
  },

  currentPlayer(s) {
    return s.toPlay;
  },

  legalMoves(s) {
    const colour = goColourToMove(s);
    const moves: number[] = [];
    for (let p = 0; p < GO_AREA; p += 1) if (goLegal(s.board, s.ko, p, colour)) moves.push(p);
    moves.push(GO_PASS);
    return moves;
  },

  apply(s, m) {
    const colour = goColourToMove(s);
    if (!goLegal(s.board, s.ko, m, colour)) throw new Error("Point " + String(m) + " is not a legal move.");
    const played = goPlay(s.board, m, colour);
    const caps: [number, number] = [s.caps[0], s.caps[1]];
    if (colour === 1) caps[0] += played.captured.length;
    else caps[1] += played.captured.length;
    const recent = s.recent.slice(-4);
    recent.push(m);
    return {
      board: played.board,
      toPlay: colour === 1 ? s.seats[1] : s.seats[0],
      seats: [s.seats[0], s.seats[1]],
      ko: played.ko,
      passes: m === GO_PASS ? s.passes + 1 : 0,
      ply: s.ply + 1,
      recent,
      prev1: s.board.slice(),
      prev1Ko: s.ko,
      prev2: s.prev1 ? s.prev1.slice() : null,
      prev2Ko: s.prev1Ko,
      caps
    };
  },

  terminal(s) {
    if (!goIsOver(s)) return null;
    const margin = goMargin(s.board);
    const black = margin > 0 ? 1 : margin < 0 ? -1 : 0;
    const value: Record<string, number> = {};
    value[s.seats[0]] = black;
    value[s.seats[1]] = -black;
    return { value };
  },

  // KataGo V7 inputs (nninputs.cpp fillRowV7) for an area-scoring, simple-ko, no-suicide,
  // no-tax game, from the side to move's point of view. Planes 22..40 hold the 19 global
  // inputs, each spread over its whole plane (the model averages them back).
  encode(s) {
    const out = new Float32Array(GO_PLANES * GO_AREA);
    const pla = goColourToMove(s);
    const b = s.board;
    const set = (feature: number, p: number) => {
      out[feature * GO_AREA + p] = 1;
    };
    const chains = goChains(b);
    for (let p = 0; p < GO_AREA; p += 1) {
      set(0, p);
      const stone = b[p];
      if (stone === 0) continue;
      set(stone === pla ? 1 : 2, p);
      const libs = chains.libs[chains.id[p]];
      if (libs === 1) set(3, p);
      else if (libs === 2) set(4, p);
      else if (libs === 3) set(5, p);
    }
    if (s.ko >= 0) set(6, s.ko);

    // Area (pass-alive) features 18, 19.
    const area = goArea(b);
    for (let p = 0; p < GO_AREA; p += 1) {
      if (area[p] === pla) set(18, p);
      else if (area[p] === -pla) set(19, p);
    }

    // The last five moves: features 9..13 (on the board), globals 0..4 (passes).
    const global = new Float32Array(GO_GLOBAL);
    const history = Math.min(5, s.recent.length);
    for (let i = 0; i < history; i += 1) {
      const move = s.recent[s.recent.length - 1 - i];
      if (move === GO_PASS) global[i] = 1;
      else set(9 + i, move);
    }

    // Ladders: 14 (now), 15 (one move ago), 16 (two moves ago), 17 (moves that ladder an
    // opponent chain with two liberties).
    const now = goLadders(b, s.ko);
    for (const p of now.laddered) set(14, p);
    for (const entry of now.working) {
      if (b[entry.chain[0]] !== -pla) continue;
      for (const move of entry.moves) set(17, move);
    }
    const prevBoard = s.ply >= 1 && s.prev1 ? s.prev1 : b;
    const prevKo = s.ply >= 1 && s.prev1 ? s.prev1Ko : s.ko;
    for (const p of goLadders(prevBoard, prevKo).laddered) set(15, p);
    const prevPrevBoard = s.ply >= 2 && s.prev2 ? s.prev2 : prevBoard;
    const prevPrevKo = s.ply >= 2 && s.prev2 ? s.prev2Ko : prevKo;
    for (const p of goLadders(prevPrevBoard, prevPrevKo).laddered) set(16, p);

    // Globals: komi from the mover's side, rules (all zero for area / simple ko / no suicide /
    // no tax), "a pass now ends the game", komi parity wave.
    const selfKomi = pla === -1 ? GO_KOMI : -GO_KOMI;
    global[5] = selfKomi / 20;
    global[14] = s.passes >= 1 ? 1 : 0;
    global[18] = goKomiWave(selfKomi);
    for (let g = 0; g < GO_GLOBAL; g += 1) {
      if (global[g] === 0) continue;
      out.fill(global[g], (GO_SPATIAL + g) * GO_AREA, (GO_SPATIAL + g + 1) * GO_AREA);
    }
    return out;
  },
  encoding: { planes: GO_PLANES, height: GO_N, width: GO_N },

  policySize: GO_AREA + 1,
  moveIndex(m) {
    return m;
  },
  moveAt(i) {
    return i;
  },

  // Area count with komi for the side to move, folded into (-1, 1). Weak; it is only the
  // fallback for a host that cannot run the network.
  heuristic(s) {
    const pla = goColourToMove(s);
    const margin = goMargin(s.board) * pla;
    if (goIsOver(s)) return margin > 0 ? 1 : margin < 0 ? -1 : 0;
    return margin / (Math.abs(margin) + GO_AREA * 0.15);
  }
};

// =====================================================================================
// The table
// =====================================================================================

const tblSettings = declareVariables({
  blackBowl: { type: "object", kind: "bag", label: "Black's bowl", description: "The bowl Black's stones come from. Leave empty: the script finds it." },
  whiteBowl: { type: "object", kind: "bag", label: "White's bowl", description: "The bowl White's stones come from. Leave empty: the script finds it." },
  blackSeat: { type: "seat", label: "Black's seat", description: "Leave empty: whoever moves first plays Black.", default: "purple" },
  whiteSeat: { type: "seat", label: "White's seat", description: "Leave empty: the other player.", default: "red" },
  dropHeight: {
    type: "number",
    label: "Drop height",
    description: "How far above a point (in feet) a bot lets go of a stone.",
    default: 0.03,
    min: 0,
    max: 1
  }
});

const TBL_BLACK = "black";
const TBL_WHITE = "white";
/** Column letters, as Go writes them: no I. */
const TBL_COLUMNS = "ABCDEFGHJKLMNOPQRST";
const TBL_SAVE_KEY = "go";
const TBL_MENU_PASS = "go-pass";
const TBL_MENU_RESIGN = "go-resign";
const TBL_MENU_NEW_GAME = "go-new-game";
const TBL_MENU_ESTIMATE = "go-estimate";
/** How long to let a stone settle before the board is read again. */
const TBL_SETTLE_SECONDS = 0.35;
/** The converted KataGo network for this board size (`manifest.aiModels[].id`). */
const BOT_MODEL_ID = "katago-" + String(GO_N) + "x" + String(GO_N);

interface TblPoint {
  p: number;
  name: string;
  position: Vec3;
}

interface TblStone {
  handle: ObjectHandle;
  /** 1 black, -1 white. */
  colour: number;
  /** The point it is on, or -1. */
  p: number;
}

interface TblReading {
  board: number[];
  stones: TblStone[];
  byPoint: (TblStone | null)[];
  crowded: number[];
}

let tblPoints: TblPoint[] | null = null;
let tblPitch = 0.15;
/** The bowls, once found: black then white. */
let tblBowls: [BagObject | null, BagObject | null] = [null, null];
let game: GoState | null = null;
let gameOver = false;
/** Why the game ended when the board does not say (a resignation); "" otherwise. */
let tblEndNote = "";
const gameSeatOf: Record<string, string | null> = { black: null, white: null };
/** A stone left where it is not a legal move, so the notice is given once. */
let tblIllegalPoint = -1;
let tblQueue: Promise<void> = Promise.resolve();

function tblDescribe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function tblRun<T>(task: () => Promise<T>): Promise<T> {
  const run = tblQueue.then(task);
  tblQueue = run.then(
    () => undefined,
    (error) => { world.log("Go: " + tblDescribe(error)); }
  );
  return run;
}

function tblColourName(colour: number): string {
  return colour === 1 ? "Black" : "White";
}

function tblColourKey(colour: number): string {
  return colour === 1 ? TBL_BLACK : TBL_WHITE;
}

function tblPointName(p: number): string {
  if (p === GO_PASS) return "pass";
  return TBL_COLUMNS.charAt(p % GO_N) + String(GO_N - Math.floor(p / GO_N));
}

function tblPlanDistance(a: Vec3, b: Vec3): number {
  const dx = a[0] - b[0];
  const dz = a[2] - b[2];
  return Math.sqrt(dx * dx + dz * dz);
}

// ---------------------------------------------------------------- stones and bowls ---

/** 1 for a black stone, -1 for white, 0 for anything that is not a Go stone. */
function tblStoneColour(object: ObjectData): number {
  if (object.kind !== "token") return 0;
  const preset = typeof object.metadata["standardPresetId"] === "string" ? String(object.metadata["standardPresetId"]) : "";
  const text = (preset + " " + (object.name ?? "")).toLowerCase();
  if (text.indexOf("go-piece-black") >= 0 || /stone.*black|black.*stone/.test(text)) return 1;
  if (text.indexOf("go-piece-white") >= 0 || /stone.*white|white.*stone/.test(text)) return -1;
  return 0;
}

/** Which bowl gives which colour: the settings, else take one stone from each to look. */
async function tblFindBowls(): Promise<boolean> {
  if (tblBowls[0] && tblBowls[1]) return true;
  if (tblSettings.blackBowl && tblSettings.whiteBowl) {
    tblBowls = [tblSettings.blackBowl, tblSettings.whiteBowl];
    return true;
  }
  const bags = await world.getAllObjects({ kind: "bag" });
  for (const bag of bags) {
    if (!bag.infinite) continue;
    const probe = await bag.takeObject({ position: [bag.position[0], bag.position[1] + 0.3, bag.position[2]] });
    if (!probe) continue;
    const colour = tblStoneColour(probe);
    probe.destroy();
    if (colour === 1 && !tblBowls[0]) tblBowls[0] = bag;
    if (colour === -1 && !tblBowls[1]) tblBowls[1] = bag;
  }
  if (!tblBowls[0] || !tblBowls[1]) {
    world.broadcast("Go: could not find a bowl of black stones and a bowl of white stones. Set them in the script's settings.");
    return false;
  }
  return true;
}

// ---------------------------------------------------------------- the points ---------

/**
 * Read the GO_AREA snap points as a grid. Rows run across from Black's side: point (x, y) has
 * x counted from Black's left and y from the far side, so A1 is Black's near-left corner, as on
 * a printed diagram.
 */
async function tblLoadPoints(): Promise<boolean> {
  const points = await world.getSnapPoints();
  if (points.length !== GO_AREA) {
    world.broadcast("Go: this board needs " + GO_AREA + " snap points, one per intersection (found " + points.length + ").");
    return false;
  }
  if (!(await tblFindBowls())) return false;
  let cx = 0;
  let cz = 0;
  for (const point of points) {
    cx += point.position[0] / GO_AREA;
    cz += point.position[2] / GO_AREA;
  }
  // Facing: from Black's bowl towards the middle of the board.
  const bowl = tblBowls[0] as BagObject;
  let fx = cx - bowl.position[0];
  let fz = cz - bowl.position[2];
  // Snap to the nearer board axis: the grid is square to it.
  if (Math.abs(fx) > Math.abs(fz)) {
    fx = Math.sign(fx);
    fz = 0;
  } else {
    fx = 0;
    fz = Math.sign(fz) || 1;
  }
  // Black's right hand, facing (fx, fz) with y up.
  const rx = -fz;
  const rz = fx;
  const along = (pos: Vec3) => (pos[0] - cx) * rx + (pos[2] - cz) * rz;
  const away = (pos: Vec3) => (pos[0] - cx) * fx + (pos[2] - cz) * fz;
  const rows = points.slice().sort((a, b) => away(b.position) - away(a.position));
  const grid: TblPoint[] = [];
  for (let y = 0; y < GO_N; y += 1) {
    const row = rows.slice(y * GO_N, y * GO_N + GO_N).sort((a, b) => along(a.position) - along(b.position));
    for (let x = 0; x < GO_N; x += 1) {
      const p = y * GO_N + x;
      grid.push({ p, name: tblPointName(p), position: [row[x].position[0], row[x].position[1], row[x].position[2]] });
    }
  }
  tblPitch = Math.max(0.01, tblPlanDistance(grid[0].position, grid[GO_N - 1].position) / (GO_N - 1));
  tblPoints = grid;
  return true;
}

/** The point a position is on (within half a line spacing, in plan view), or -1. */
function tblPointAt(position: Vec3): number {
  if (!tblPoints) return -1;
  let best = -1;
  let bestDistance = tblPitch * 0.5;
  for (const point of tblPoints) {
    const distance = tblPlanDistance(position, point.position);
    if (distance < bestDistance) {
      best = point.p;
      bestDistance = distance;
    }
  }
  return best;
}

async function tblRead(): Promise<TblReading> {
  const handles = await world.getAllObjects({ kind: "token" });
  const board: number[] = [];
  const byPoint: (TblStone | null)[] = [];
  for (let p = 0; p < GO_AREA; p += 1) {
    board.push(0);
    byPoint.push(null);
  }
  const stones: TblStone[] = [];
  const crowded: number[] = [];
  for (const handle of handles) {
    const colour = tblStoneColour(handle);
    if (colour === 0) continue;
    const stone: TblStone = { handle, colour, p: tblPointAt(handle.position) };
    stones.push(stone);
    if (stone.p < 0) continue;
    if (byPoint[stone.p]) {
      if (crowded.indexOf(stone.p) < 0) crowded.push(stone.p);
      continue;
    }
    byPoint[stone.p] = stone;
    board[stone.p] = colour;
  }
  return { board, stones, byPoint, crowded };
}

function tblStoneCount(board: number[]): number {
  let total = 0;
  for (const value of board) if (value !== 0) total += 1;
  return total;
}

// ---------------------------------------------------------------- seats --------------

function tblSeatIsBot(seat: string | null): boolean {
  if (!seat) return false;
  return world.getPlayers().some((player) => player.seat === seat && player.isBot);
}

function tblColourIsBot(colour: number): boolean {
  return tblSeatIsBot(gameSeatOf[tblColourKey(colour)]);
}

function tblSeatOfPeer(peerId: string): string {
  const players = world.getPlayers();
  let found = players.find((player) => player.peerId === peerId);
  if (!found && (peerId === "You" || peerId === "Host" || peerId === "System")) {
    found = players.find((player) => player.isHost);
  }
  return found && found.seat ? found.seat : "@" + peerId;
}

function tblSeatOccupied(seat: string): boolean {
  return world.getPlayers().some((player) => (seat.charAt(0) === "@" ? "@" + player.peerId === seat : player.seat === seat));
}

/** Give `colour` to `seat` unless the colours are already settled (by the settings, by play or by a ranked match). */
function tblClaimColour(seat: string | null, colour: number): void {
  if (mtcSeatsLocked) return;
  const black = tblSettings.blackSeat;
  const white = tblSettings.whiteSeat;
  if (black && gameSeatOf[TBL_BLACK] === null && tblSeatOccupied(black)) gameSeatOf[TBL_BLACK] = black;
  if (white && gameSeatOf[TBL_WHITE] === null && tblSeatOccupied(white)) gameSeatOf[TBL_WHITE] = white;
  if (!seat) return;
  const key = tblColourKey(colour);
  const other = tblColourKey(-colour);
  if (gameSeatOf[key] === null && gameSeatOf[other] !== seat) gameSeatOf[key] = seat;
  if (gameSeatOf[other] === null && gameSeatOf[key] !== null) {
    const opponent = world.getPlayers().find((player) => player.seat !== null && player.seat !== gameSeatOf[key]);
    if (opponent && opponent.seat) gameSeatOf[other] = opponent.seat;
  }
}

function tblColourOfSeat(seat: string | null): number {
  if (!game) return 0;
  if (seat !== null && gameSeatOf[TBL_BLACK] === seat) return 1;
  if (seat !== null && gameSeatOf[TBL_WHITE] === seat) return -1;
  tblClaimColour(seat, goColourToMove(game));
  if (seat !== null && gameSeatOf[TBL_BLACK] === seat) return 1;
  if (seat !== null && gameSeatOf[TBL_WHITE] === seat) return -1;
  return 0;
}

function tblPlayerName(colour: number): string {
  const seat = gameSeatOf[tblColourKey(colour)];
  const player = seat ? world.getPlayers().find((entry) => entry.seat === seat || "@" + entry.peerId === seat) : undefined;
  const name = player && player.displayName ? player.displayName : "";
  return name.length > 0 ? tblColourName(colour) + " (" + name + ")" : tblColourName(colour);
}

/** A real seat id for the turn glow and scores (a seatless person's "@" id is not one). */
function tblRealSeat(colour: number): string | null {
  const seat = gameSeatOf[tblColourKey(colour)];
  return seat && seat.charAt(0) !== "@" ? seat : null;
}

// ---------------------------------------------------------------- the match ----------

let mtcRecording = false;
let mtcPending: GoMove[] = [];
let mtcSeatsLocked = false;

function replay(rules: RulesKernel<GoState, GoMove>, moves: readonly unknown[]): GoState {
  let state = rules.initial([TBL_BLACK, TBL_WHITE]);
  for (const move of moves) state = rules.apply(state, Number(move));
  return state;
}

function mtcRunning(): MatchInfo | null {
  if (typeof match === "undefined") return null;
  const info = match.current();
  return info !== null && (info.status === "opening" || info.status === "live" || info.status === "ending") ? info : null;
}

function mtcRankedLive(): boolean {
  const info = mtcRunning();
  return info !== null && info.ranked && info.status !== "ending" && !gameOver;
}

function mtcLockSeats(info: MatchInfo): void {
  mtcSeatsLocked = false;
  if (!info.ranked || info.participants.length !== 2) return;
  gameSeatOf[TBL_BLACK] = info.participants[0].seat;
  gameSeatOf[TBL_WHITE] = info.participants[1].seat;
  mtcSeatsLocked = true;
}

function mtcStopRecording(why: string): void {
  mtcPending = [];
  if (!mtcRecording) return;
  mtcRecording = false;
  if (!mtcRunning()) return;
  match.abort(why).catch((error) => { world.log("Go: could not stop the match (" + tblDescribe(error) + ")."); });
}

async function mtcStart(): Promise<void> {
  mtcPending = [];
  mtcRecording = false;
  mtcSeatsLocked = false;
  if (typeof match === "undefined") return;
  const running = mtcRunning();
  if (running) {
    if (running.ranked) {
      world.log("Go: a ranked match is still running, so this game is not recorded.");
      return;
    }
    try {
      await match.abort("new game");
    } catch (error) {
      world.log("Go: could not stop the previous match (" + tblDescribe(error) + ").");
    }
  }
  const black = tblSettings.blackSeat;
  const white = tblSettings.whiteSeat;
  const seats = black && white && black !== white && tblSeatOccupied(black) && tblSeatOccupied(white) ? [black, white] : null;
  let info: MatchInfo;
  try {
    info = await match.start(seats ? { kernel, seats } : { kernel });
  } catch (error) {
    world.log("Go: this game is not recorded as a match (" + tblDescribe(error) + ").");
    return;
  }
  if (!info || info.status !== "live") return;
  if (info.ranked && info.participants.length !== 2) {
    mtcRecording = true;
    mtcStopRecording("go needs two players");
    return;
  }
  mtcRecording = true;
  mtcLockSeats(info);
}

/** After a reload: pick the running match back up with the SAME kernel (see the Othello script). */
async function mtcResume(): Promise<void> {
  mtcPending = [];
  mtcRecording = false;
  mtcSeatsLocked = false;
  const info = mtcRunning();
  if (!info) return;
  if (info.status !== "live") {
    world.log("Go: the running match is " + info.status + ", so this game is not recorded.");
    return;
  }
  let resumed: MatchInfo;
  try {
    resumed = await match.start({ kernel });
  } catch (error) {
    world.log("Go: could not pick the running match back up (" + tblDescribe(error) + "), so this game is not recorded.");
    return;
  }
  if (!resumed || resumed.id !== info.id || resumed.status !== "live") {
    world.log("Go: the running match could not be picked back up, so this game is not recorded.");
    return;
  }
  mtcRecording = true;
  mtcLockSeats(resumed);
}

function tblApply(move: GoMove): number[] {
  if (!game) return [];
  const colour = goColourToMove(game);
  const captured = move === GO_PASS ? [] : goPlay(game.board, move, colour).captured;
  game = kernel.apply(game, move);
  if (mtcRecording) mtcPending.push(move);
  return captured;
}

function mtcFlush(): void {
  const moves = mtcPending;
  mtcPending = [];
  if (!mtcRecording) return;
  for (const move of moves) {
    try {
      match.move(move);
    } catch (error) {
      world.log("Go: the match stopped recording (" + tblDescribe(error) + ").");
      mtcRecording = false;
      return;
    }
  }
}

/** The game is over on the board: end the match with the kernel's result (never `match.abort` here). */
function mtcEnd(): void {
  if (!game) return;
  if (!mtcRecording) {
    if (mtcRunning()) world.log("Go: the game is over but its match was not being recorded, so the table ends it with no result.");
    return;
  }
  mtcFlush();
  const outcome = kernel.terminal(game);
  const info = mtcRunning();
  if (!outcome || !info || !mtcRecording) {
    world.log("Go: the game is over but its match could not be ended (" + (!outcome ? "the rules say it is not over" : !info ? "no match is running" : "it stopped recording") + ").");
    return;
  }
  mtcRecording = false;
  const blackSeat = gameSeatOf[TBL_BLACK];
  const whiteSeat = gameSeatOf[TBL_WHITE];
  const seats = info.participants.map((participant) => participant.seat);
  if (!blackSeat || !whiteSeat || seats.length !== 2 || seats[0] !== blackSeat || seats[1] !== whiteSeat) {
    world.log("Go: the match's seats are not Black then White, so its result cannot be reported; the table ends it with no result.");
    return;
  }
  const count = goAreaCount(game.board);
  const scores: Record<string, number> = {};
  scores[blackSeat] = count.black;
  scores[whiteSeat] = count.white + GO_KOMI;
  const blackValue = outcome.value[TBL_BLACK];
  const result: MatchResult = blackValue === 0 ? { draw: true } : { winner: blackValue > 0 ? blackSeat : whiteSeat };
  match.end(result, { reason: game.passes >= 2 ? "points" : "move limit", scores }).catch((error) => {
    world.log("Go: the match result was not accepted (" + tblDescribe(error) + ").");
  });
}

// ---------------------------------------------------------------- saving and status --

async function tblSave(): Promise<void> {
  if (!game) return;
  await world.setSavedData(JSON.stringify({
    v: 1,
    n: GO_N,
    game,
    over: gameOver,
    note: tblEndNote,
    black: gameSeatOf[TBL_BLACK],
    white: gameSeatOf[TBL_WHITE]
  }), TBL_SAVE_KEY);
}

function tblValidState(value: unknown): value is GoState {
  if (!value || typeof value !== "object") return false;
  const s = value as Partial<GoState>;
  const isBoard = (b: unknown) => Array.isArray(b) && b.length === GO_AREA && b.every((v) => v === 0 || v === 1 || v === -1);
  return isBoard(s.board) &&
    (s.toPlay === TBL_BLACK || s.toPlay === TBL_WHITE) &&
    Array.isArray(s.seats) && s.seats[0] === TBL_BLACK && s.seats[1] === TBL_WHITE &&
    typeof s.ko === "number" && typeof s.passes === "number" && typeof s.ply === "number" &&
    Array.isArray(s.recent) && s.recent.every((m) => Number.isInteger(m) && m >= 0 && m <= GO_PASS) &&
    (s.prev1 === null || isBoard(s.prev1)) && (s.prev2 === null || isBoard(s.prev2)) &&
    typeof s.prev1Ko === "number" && typeof s.prev2Ko === "number" &&
    Array.isArray(s.caps) && s.caps.length === 2;
}

async function tblLoadSaved(): Promise<boolean> {
  const raw = await world.getSavedData(TBL_SAVE_KEY);
  if (!raw) return false;
  try {
    const data = JSON.parse(raw) as { n?: unknown; game?: unknown; over?: unknown; note?: unknown; black?: unknown; white?: unknown };
    if (data.n !== GO_N || !tblValidState(data.game)) return false;
    game = data.game;
    gameOver = data.over === true;
    tblEndNote = gameOver && typeof data.note === "string" ? data.note.slice(0, 160) : "";
    gameSeatOf[TBL_BLACK] = typeof data.black === "string" ? data.black : null;
    gameSeatOf[TBL_WHITE] = typeof data.white === "string" ? data.white : null;
    return true;
  } catch (error) {
    return false;
  }
}

function tblScoreLine(): string {
  if (!game) return "";
  const count = goAreaCount(game.board);
  const white = count.white + GO_KOMI;
  const margin = count.black - white;
  const tally = "Black " + count.black + ", White " + count.white + " + " + GO_KOMI + " komi = " + white + ".";
  if (margin === 0) return tally + " A draw.";
  return tally + " " + tblPlayerName(margin > 0 ? 1 : -1) + " wins by " + Math.abs(margin) + ".";
}

function tblSetGameOver(result: { winner: string } | { draw: true } | null): void {
  if (typeof world.setGameOver === "function") world.setGameOver(result);
}

function tblDeclareGameOver(): void {
  if (!game) return;
  const margin = goMargin(game.board);
  if (margin === 0) {
    tblSetGameOver({ draw: true });
    return;
  }
  const winner = tblRealSeat(margin > 0 ? 1 : -1);
  if (winner) tblSetGameOver({ winner });
}

/** Whose turn (a glow on that seat) and each side's prisoners beside its name. */
function tblRenderStatus(): void {
  if (!game || !tblPoints) return;
  const black = tblRealSeat(1);
  const white = tblRealSeat(-1);
  const scores: Record<string, number> = {};
  if (black) scores[black] = game.caps[0];
  if (white) scores[white] = game.caps[1];
  world.setScores(scores);
  world.setTurn(gameOver ? null : tblRealSeat(goColourToMove(game)));
}

// ---------------------------------------------------------------- moves on the table -

/** Take the stones a move captured off the board. */
function tblRemoveCaptured(reading: TblReading, captured: number[]): void {
  for (const p of captured) {
    const stone = reading.byPoint[p];
    if (stone) {
      stone.handle.destroy();
      reading.byPoint[p] = null;
      reading.board[p] = 0;
    } else {
      world.log("Go: no stone on " + tblPointName(p) + " to take off.");
    }
  }
}

function tblMoveLine(colour: number, move: GoMove, captured: number): string {
  if (move === GO_PASS) return tblPlayerName(colour) + " passes.";
  return tblPlayerName(colour) + " plays " + tblPointName(move) + (captured > 0 ? " and captures " + captured + (captured === 1 ? " stone." : " stones.") : ".");
}

/** After any move: record, find the end of the game, save, redraw. */
async function tblAfterMove(): Promise<void> {
  if (!game) return;
  mtcFlush();
  if (goIsOver(game) && !gameOver) {
    gameOver = true;
    world.broadcast((game.passes >= 2 ? "Both players passed. " : "The move limit is reached. ") + "Game over. " + tblScoreLine());
    mtcEnd();
    tblDeclareGameOver();
  } else if (!gameOver && game.passes === 1) {
    world.broadcast(tblPlayerName(goColourToMove(game)) + ": pass too and the game ends and is counted as the board stands - capture dead stones first.");
  }
  await tblSave();
  tblRenderStatus();
}

/** A bot (or the script) plays `move` for `colour`. */
async function tblPlay(move: GoMove, colour: number): Promise<void> {
  if (!game || !tblPoints) return;
  if (move === GO_PASS) {
    tblApply(GO_PASS);
    world.broadcast(tblMoveLine(colour, GO_PASS, 0));
    await tblAfterMove();
    return;
  }
  const reading = await tblRead();
  const point = tblPoints[move];
  if (reading.byPoint[move]) throw new Error(point.name + " is already taken on the table.");
  const bowl = tblBowls[colour === 1 ? 0 : 1];
  if (!bowl) throw new Error("there is no bowl of " + tblColourName(colour).toLowerCase() + " stones.");
  const stone = await bowl.takeObject({ position: [point.position[0], point.position[1] + tblSettings.dropHeight, point.position[2]] });
  if (!stone) throw new Error("no stone came out of the " + tblColourName(colour).toLowerCase() + " bowl.");
  const captured = tblApply(move);
  tblRemoveCaptured(reading, captured);
  world.broadcast(tblMoveLine(colour, move, captured.length));
  await world.wait(TBL_SETTLE_SECONDS);
  await tblAfterMove();
}

/** Accept what the table shows as the position (history cleared), keeping the side to move. */
async function tblAdopt(reading: TblReading, why: string): Promise<void> {
  if (!game) return;
  world.log("Go: " + why + " Following the table.");
  mtcStopRecording("board edited by hand");
  const fresh = kernel.initial([TBL_BLACK, TBL_WHITE]);
  game = { ...fresh, board: reading.board.slice(), toPlay: game.toPlay, caps: [game.caps[0], game.caps[1]], ply: game.ply };
  if (gameOver) tblSetGameOver(null);
  gameOver = false;
  tblEndNote = "";
  tblIllegalPoint = -1;
  await tblAfterMove();
}

/** Put the stones on the points back to `board`: extras off the table, missing ones from the bowls. */
async function tblLayOut(reading: TblReading, board: number[]): Promise<void> {
  if (!tblPoints) return;
  for (let p = 0; p < GO_AREA; p += 1) {
    const stone = reading.byPoint[p];
    if (stone && stone.colour !== board[p]) {
      stone.handle.destroy();
      reading.byPoint[p] = null;
    }
  }
  for (const stone of reading.stones) {
    // Stones dropped on the board between points (or crowded onto one) go too.
    if (stone.p < 0 && tblPlanDistance(stone.handle.position, tblPoints[Math.floor(GO_AREA / 2)].position) < tblPitch * (GO_N / 2 + 0.5)) {
      stone.handle.destroy();
    }
  }
  for (const p of reading.crowded) {
    const keep = reading.byPoint[p];
    for (const stone of reading.stones) if (stone.p === p && stone !== keep) stone.handle.destroy();
  }
  for (let p = 0; p < GO_AREA; p += 1) {
    if (board[p] === 0 || reading.byPoint[p]) continue;
    const bowl = tblBowls[board[p] === 1 ? 0 : 1];
    const point = tblPoints[p];
    if (bowl) await bowl.takeObject({ position: [point.position[0], point.position[1] + tblSettings.dropHeight, point.position[2]] });
  }
}

/**
 * Compare the table with the game. One new stone on an empty point is a move by the side to
 * move: legal, it is played (and the captured stones come off); not legal, it is left with a
 * notice. Anything else is a hand edit: put back in a ranked match, followed otherwise.
 */
async function tblSync(actor: string | null): Promise<void> {
  if (!game || !tblPoints) return;
  const reading = await tblRead();
  if (reading.crowded.length > 0) {
    world.log("Go: more than one stone on " + reading.crowded.map(tblPointName).join(", ") + "; the first one found counts.");
  }
  const changed: number[] = [];
  for (let p = 0; p < GO_AREA; p += 1) if (reading.board[p] !== game.board[p]) changed.push(p);
  if (changed.length === 0) {
    tblIllegalPoint = -1;
    return;
  }
  const placed = changed.length === 1 && game.board[changed[0]] === 0 ? changed[0] : -1;
  if (placed >= 0 && !gameOver) {
    const colour = goColourToMove(game);
    const name = tblPointName(placed);
    const notice = (text: string) => {
      if (tblIllegalPoint !== placed) world.broadcast(text);
      tblIllegalPoint = placed;
    };
    if (reading.board[placed] !== colour) {
      notice("It is " + tblColourName(colour) + "'s move - take the " + tblColourName(-colour).toLowerCase() + " stone off " + name + ".");
      return;
    }
    if (tblColourIsBot(colour)) {
      notice("It is " + tblPlayerName(colour) + "'s turn - the stone on " + name + " does not count.");
      return;
    }
    const mover = gameSeatOf[tblColourKey(colour)];
    if (actor !== null && mover !== null && tblSeatOccupied(mover) && mover !== tblSeatOfPeer(actor)) {
      notice("It is " + tblPlayerName(colour) + "'s move - the stone on " + name + " does not count.");
      return;
    }
    if (!goLegal(game.board, game.ko, placed, colour)) {
      notice(name + (placed === game.ko ? " is a ko: play somewhere else first, then you may take back." : " is not a legal move (it would have no liberties).") + " Take that stone back.");
      return;
    }
    tblIllegalPoint = -1;
    if (actor !== null) tblClaimColour(tblSeatOfPeer(actor), colour);
    const captured = tblApply(placed);
    tblRemoveCaptured(reading, captured);
    world.broadcast(tblMoveLine(colour, placed, captured.length));
    await world.wait(TBL_SETTLE_SECONDS);
    await tblAfterMove();
    const next = goColourToMove(game);
    if (!gameOver && world.getTurn().enabled && tblColourIsBot(next)) {
      world.broadcast("Press End Turn to let " + tblPlayerName(next) + " move.");
    }
    return;
  }
  if (gameOver && changed.every((p) => reading.board[p] === 0)) {
    // Clearing the board after a game is not an edit to follow.
    return;
  }
  const where = changed.slice(0, 6).map(tblPointName).join(", ") + (changed.length > 6 ? "..." : "");
  if (mtcRankedLive()) {
    world.broadcast("Ranked match: the board was changed by hand (" + where + "), so it is put back.");
    await tblLayOut(reading, game.board);
    tblIllegalPoint = -1;
    await world.wait(TBL_SETTLE_SECONDS);
    return;
  }
  await tblAdopt(reading, "The board was changed by hand (" + where + ").");
}

// ---------------------------------------------------------------- new game -----------

async function tblNewGame(): Promise<void> {
  if (!tblPoints) return;
  const start = kernel.initial([TBL_BLACK, TBL_WHITE]);
  const reading = await tblRead();
  // Every stone on or near the board goes; stones in the bowls stay.
  for (const stone of reading.stones) {
    if (stone.p >= 0 || tblPlanDistance(stone.handle.position, tblPoints[Math.floor(GO_AREA / 2)].position) < tblPitch * (GO_N / 2 + 0.5)) {
      stone.handle.destroy();
    }
  }
  game = start;
  gameOver = false;
  tblSetGameOver(null);
  tblEndNote = "";
  tblIllegalPoint = -1;
  gameSeatOf[TBL_BLACK] = null;
  gameSeatOf[TBL_WHITE] = null;
  await world.wait(TBL_SETTLE_SECONDS);
  await mtcStart();
  tblClaimColour(null, 1);
  const rules = "Area scoring, " + GO_KOMI + " komi, simple ko.";
  if (mtcSeatsLocked) {
    world.broadcast("New " + GO_N + "x" + GO_N + " game, ranked: " + tblPlayerName(1) + " against " + tblPlayerName(-1) + ". " + rules);
  } else if (gameSeatOf[TBL_BLACK] && gameSeatOf[TBL_WHITE]) {
    world.broadcast("New " + GO_N + "x" + GO_N + " game: " + tblPlayerName(1) + " against " + tblPlayerName(-1) + ". " + rules);
  } else {
    world.broadcast("New " + GO_N + "x" + GO_N + " game. Black moves first. " + rules);
  }
  await tblAfterMove();
}

// ---------------------------------------------------------------- start up -----------

async function tblEnsureReady(): Promise<boolean> {
  if (tblPoints && game) return true;
  if (!tblPoints && !(await tblLoadPoints())) return false;
  if (game) return true;
  if (await tblLoadSaved()) {
    await mtcResume();
    await tblSync(null);
    tblRenderStatus();
    return true;
  }
  const reading = await tblRead();
  if (tblStoneCount(reading.board) === 0) {
    await tblNewGame();
    return game !== null;
  }
  // A position nobody saved: follow it, Black to move on an even count.
  const fresh = kernel.initial([TBL_BLACK, TBL_WHITE]);
  game = { ...fresh, board: reading.board.slice(), toPlay: tblStoneCount(reading.board) % 2 === 0 ? TBL_BLACK : TBL_WHITE };
  world.log("Go: picked up a game in progress; " + game.toPlay + " to move.");
  gameOver = false;
  await tblAfterMove();
  return true;
}

// ---------------------------------------------------------------- bots ---------------

/**
 * The AI bot's levels. All play the same KataGo network; they differ in how they use it:
 * - beginner / easy: one look at the network's move probabilities, picking among the likelier
 *   moves at random (`temperature`, and moves below `floor` of the best one's probability are
 *   never picked) - human-like mistakes rather than random ones;
 * - medium: the network's single most likely move;
 * - hard: a tree search (`ai.mcts`) of `simulations` playouts.
 */
interface BotLevel {
  simulations: number;
  temperature: number;
  floor: number;
}
const BOT_LEVELS: Record<string, BotLevel> = {
  beginner: { simulations: 0, temperature: 1.6, floor: 0.02 },
  easy: { simulations: 0, temperature: 1, floor: 0.05 },
  medium: { simulations: 0, temperature: 0, floor: 1 },
  hard: { simulations: GO_N <= 9 ? 200 : GO_N <= 13 ? 100 : 48, temperature: 0, floor: 1 }
};

/** A tiny, seedable generator for the bots' own sampling (kept out of the kernel). */
let botSeed = 0x9e3779b1;
function botRandom(): number {
  botSeed = (botSeed + 0x6d2b79f5) >>> 0;
  let t = botSeed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

interface BotEval {
  policy: Float32Array;
  value: number;
  ownership: Float32Array | null;
  lead: number | null;
}

async function botEvaluate(state: GoState, signal: BotAbortSignal | undefined): Promise<BotEval> {
  const out = await ai.evaluate(BOT_MODEL_ID, { board: kernel.encode(state) }, signal ? { signal } : undefined);
  const policy = out["policy"];
  if (!policy || policy.length !== GO_AREA + 1) throw new Error("ai-shape-mismatch");
  const value = out["value"];
  const lead = out["lead"];
  return {
    policy,
    value: value && value.length > 0 ? value[0] : 0,
    ownership: out["ownership"] && out["ownership"].length === GO_AREA ? out["ownership"] : null,
    lead: lead && lead.length > 0 ? lead[0] : null
  };
}

/** Pick from the network's policy over the legal moves (softmax of logits / temperature). */
function botPickFromPolicy(state: GoState, policy: Float32Array, temperature: number, floor: number): GoMove {
  const legal = kernel.legalMoves(state);
  let best = legal[0];
  let bestLogit = -Infinity;
  for (const move of legal) {
    if (policy[move] > bestLogit) {
      bestLogit = policy[move];
      best = move;
    }
  }
  if (temperature <= 0) return best;
  const weights: number[] = [];
  let total = 0;
  for (const move of legal) {
    // Probability relative to the best move; anything under `floor` of it is never picked.
    const relative = Math.exp(policy[move] - bestLogit);
    const weight = relative >= floor ? Math.pow(relative, 1 / temperature) : 0;
    weights.push(weight);
    total += weight;
  }
  let pick = botRandom() * total;
  for (let i = 0; i < legal.length; i += 1) {
    pick -= weights[i];
    if (pick <= 0 && weights[i] > 0) return legal[i];
  }
  return best;
}

/**
 * Never end a game it is winning by passing too soon: when the opponent has just passed (so a
 * pass ends the game) and the count as the board stands is a loss for the bot while the
 * network still thinks it is ahead, there are dead stones to take off first - play on.
 */
function botAvoidLosingPass(state: GoState, move: GoMove, evaluation: BotEval | null): GoMove {
  if (move !== GO_PASS || state.passes < 1) return move;
  const colour = goColourToMove(state);
  if (goMargin(state.board) * colour > 0) return move;
  if (!evaluation || evaluation.lead === null || evaluation.lead <= 0) return move;
  let best: GoMove = GO_PASS;
  let bestLogit = -Infinity;
  for (const candidate of kernel.legalMoves(state)) {
    if (candidate === GO_PASS) continue;
    // Not into its own territory's eyes: only points the network does not already own.
    if (evaluation.ownership && evaluation.ownership[candidate] > 0.9 && goImmediateLibs(state.board, candidate) === 0) continue;
    if (evaluation.policy[candidate] > bestLogit) {
      bestLogit = evaluation.policy[candidate];
      best = candidate;
    }
  }
  return best;
}

/** The scripted fallback when the host cannot run the network: a light search on the area count. */
async function botFallbackMove(state: GoState, signal: BotAbortSignal | undefined): Promise<GoMove> {
  const result = await ai.mcts({ kernel, state, simulations: GO_N <= 9 ? 64 : 24, signal });
  return result.move;
}

async function botChooseAi(state: GoState, difficultyId: string | null, signal: BotAbortSignal | undefined): Promise<GoMove> {
  const level = difficultyId !== null && BOT_LEVELS[difficultyId] !== undefined ? BOT_LEVELS[difficultyId] : BOT_LEVELS["medium"];
  let evaluation: BotEval | null = null;
  try {
    evaluation = await botEvaluate(state, signal);
  } catch (error) {
    world.log("Go: the network is not available on this host (" + tblDescribe(error) + "); playing a simple search instead.");
    return botFallbackMove(state, signal);
  }
  let move: GoMove;
  if (level.simulations > 0) {
    const result = await ai.mcts({ kernel, modelId: BOT_MODEL_ID, state, simulations: level.simulations, signal });
    move = result.move;
  } else {
    move = botPickFromPolicy(state, evaluation.policy, level.temperature, level.floor);
  }
  return botAvoidLosingPass(state, move, evaluation);
}

type BotChooser = (state: GoState, difficultyId: string | null, signal: BotAbortSignal | undefined) => Promise<GoMove>;

const BOT_CHOOSERS: Record<string, BotChooser> = {
  katago: botChooseAi,
  // The scripted bot: a search on the area count, no network. Weak, but it runs anywhere.
  search: async (state, _difficulty, signal) => botFallbackMove(state, signal)
};
const BOT_PACE_SECONDS = 0.6;

async function botTakeTurn(ctx: BotTurnContext, chooser: BotChooser): Promise<void> {
  await tblRun(async () => {
    if (!(await tblEnsureReady()) || !game) throw new Error("the board is not set up (see the chat).");
    await tblSync(null);
    if (gameOver) return;
    const colour = tblColourOfSeat(ctx.seat);
    if (colour === 0) throw new Error("this bot's seat plays neither colour.");
    if (goColourToMove(game) !== colour) {
      world.broadcast("Waiting for " + tblPlayerName(-colour) + " to move.");
      return;
    }
    const move = await chooser(game, ctx.difficultyId, ctx.signal);
    if (ctx.signal.aborted) return;
    await tblPlay(move, colour);
  });
}

bots.register({ id: "katago", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["katago"]) });
bots.register({ id: "search", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["search"]) });

/** Turn mode off (every solo table): the script moves its seated bots itself. */
async function botDriveSeatedBots(): Promise<void> {
  for (let guard = 0; guard < GO_MAX_PLIES; guard += 1) {
    if (!game || gameOver || world.getTurn().enabled) return;
    const seatedBots = world.getPlayers().filter((player) => player.isBot && player.seat !== null);
    if (seatedBots.length === 0) return;
    if (gameSeatOf[TBL_BLACK] === null && gameSeatOf[TBL_WHITE] === null && seatedBots.length >= 2) {
      gameSeatOf[TBL_BLACK] = seatedBots[0].seat;
      gameSeatOf[TBL_WHITE] = seatedBots[1].seat;
    }
    const colour = goColourToMove(game);
    let seat = gameSeatOf[tblColourKey(colour)];
    if (seat === null && gameSeatOf[tblColourKey(-colour)] !== null) {
      // The person has a colour; a bot takes the other.
      const free = seatedBots.find((entry) => entry.seat !== gameSeatOf[tblColourKey(-colour)]);
      if (free && free.seat) {
        gameSeatOf[tblColourKey(colour)] = free.seat;
        seat = free.seat;
      }
    }
    const player = seatedBots.find((entry) => entry.seat === seat);
    if (!player) return;
    const chooser = player.botId !== null ? BOT_CHOOSERS[player.botId] : undefined;
    if (!chooser) {
      world.broadcast("Go: this script has no bot called \"" + String(player.botId) + "\".");
      return;
    }
    await world.wait(BOT_PACE_SECONDS);
    if (!game || gameOver) return;
    const move = await chooser(game, player.difficultyId, undefined);
    await tblPlay(move, colour);
  }
}

function botKick(): void {
  void tblRun(async () => {
    if (await tblEnsureReady()) await botDriveSeatedBots();
  });
}

// ---------------------------------------------------------------- people --------------

globalEvents.onObjectDropped.add((object, context) => {
  if (tblStoneColour(object) === 0 || context.actor === "Script") return;
  void tblRun(async () => {
    if (!(await tblEnsureReady())) return;
    await world.wait(TBL_SETTLE_SECONDS);
    await tblSync(context.actor);
    await botDriveSeatedBots();
  });
});

globalEvents.onPlayerJoined.add(() => botKick());
globalEvents.onSeatChanged.add(() => botKick());

// The menu goes on the entity this script is attached to: the variant's board, whatever its kind
// (the 19x19 board is an imported model, kind "custom"; the others are kind "board").
const TBL_MENU_MATCH = { objectIds: [refObject.id] };
world.addObjectMenuItem({ id: TBL_MENU_PASS, label: "Pass", match: TBL_MENU_MATCH, order: 0 });
world.addObjectMenuItem({ id: TBL_MENU_ESTIMATE, label: "Estimate the score", match: TBL_MENU_MATCH, order: 1 });
world.addObjectMenuItem({ id: TBL_MENU_NEW_GAME, label: "New game", match: TBL_MENU_MATCH, order: 2 });
world.addObjectMenuItem({ id: TBL_MENU_RESIGN, label: "Resign", match: TBL_MENU_MATCH, order: 3, danger: true });

/** "Estimate the score": the network's view of who owns each point, when this host can run it. */
async function tblEstimate(): Promise<void> {
  if (!game) return;
  try {
    const evaluation = await botEvaluate(game, undefined);
    if (evaluation.ownership) {
      const pla = goColourToMove(game);
      let black = 0;
      for (let p = 0; p < GO_AREA; p += 1) black += evaluation.ownership[p] * pla;
      // Ownership runs from -1 (White) to 1 (Black) per point after the flip above.
      const margin = black - GO_KOMI;
      const leader = margin >= 0 ? 1 : -1;
      const lead = evaluation.lead !== null ? Math.abs(evaluation.lead) : Math.abs(margin);
      world.broadcast("Estimate: " + tblColourName(leader) + " is ahead by about " + lead.toFixed(1) + " points (the AI's view, komi included). Counting the board as it stands now: " + tblScoreLine());
      return;
    }
  } catch (error) {
    // No network on this host: just count the board.
  }
  world.broadcast("Counting the board as it stands now: " + tblScoreLine());
}

globalEvents.onObjectMenuItem.add((object, itemId, context) => {
  void tblRun(async () => {
    if (itemId === TBL_MENU_NEW_GAME) {
      if (!tblPoints && !(await tblLoadPoints())) return;
      if (mtcRankedLive()) {
        world.broadcast("A ranked match is being played: finish it, resign or agree a draw before starting a new game.");
        return;
      }
      await tblNewGame();
      await botDriveSeatedBots();
      return;
    }
    if (!(await tblEnsureReady()) || !game) return;
    if (itemId === TBL_MENU_ESTIMATE) {
      await tblEstimate();
      return;
    }
    if (gameOver) return;
    const colour = goColourToMove(game);
    const seat = tblSeatOfPeer(context.actor);
    if (itemId === TBL_MENU_PASS) {
      const mover = gameSeatOf[tblColourKey(colour)];
      if (tblColourIsBot(colour) || (mover !== null && tblSeatOccupied(mover) && mover !== seat)) {
        world.broadcast("It is " + tblPlayerName(colour) + "'s move, so only they can pass.");
        return;
      }
      await tblSync(context.actor);
      if (!game || gameOver || goColourToMove(game) !== colour) return;
      tblClaimColour(seat, colour);
      tblApply(GO_PASS);
      world.broadcast(tblMoveLine(colour, GO_PASS, 0));
      await tblAfterMove();
      await botDriveSeatedBots();
      return;
    }
    if (itemId === TBL_MENU_RESIGN) {
      const running = mtcRunning();
      if (running && running.ranked) {
        world.broadcast("This is a ranked match: use Resign in the match bar to resign.");
        return;
      }
      let loser = gameSeatOf[TBL_BLACK] === seat ? 1 : gameSeatOf[TBL_WHITE] === seat ? -1 : 0;
      if (loser === 0) loser = colour;
      mtcStopRecording("resigned");
      gameOver = true;
      tblEndNote = tblColourName(loser) + " resigns.";
      world.broadcast(tblPlayerName(loser) + " resigns. " + tblPlayerName(-loser) + " wins.");
      const winner = tblRealSeat(-loser);
      if (winner) tblSetGameOver({ winner });
      await tblSave();
      tblRenderStatus();
    }
  });
});

// ---------------------------------------------------------------- match events -------

if (typeof match !== "undefined") {
  match.onForfeit.add((participant) => {
    void tblRun(async () => {
      const colour = participant.seat === gameSeatOf[TBL_BLACK] ? 1 : participant.seat === gameSeatOf[TBL_WHITE] ? -1 : 0;
      const who = colour !== 0 ? tblPlayerName(colour) : participant.seat;
      world.broadcast(who + " forfeits the match.");
      mtcPending = [];
      mtcRecording = false;
      if (!game || gameOver || colour === 0) return;
      gameOver = true;
      tblEndNote = tblColourName(colour) + " forfeits.";
      const winner = tblRealSeat(-colour);
      if (winner) tblSetGameOver({ winner });
      await tblSave();
      tblRenderStatus();
    });
  });

  match.onDrawAgreed.add(() => {
    void tblRun(async () => {
      mtcPending = [];
      mtcRecording = false;
      if (!game || gameOver) return;
      gameOver = true;
      tblEndNote = "Draw agreed.";
      world.broadcast("Draw agreed.");
      tblSetGameOver({ draw: true });
      await tblSave();
      tblRenderStatus();
    });
  });

  match.onTakeback.add((info) => {
    void tblRun(async () => {
      if (!tblPoints) return;
      mtcPending = [];
      game = replay(kernel, match.moves());
      const wasOver = gameOver;
      gameOver = goIsOver(game);
      if (wasOver && !gameOver) tblSetGameOver(null);
      tblEndNote = "";
      tblIllegalPoint = -1;
      world.broadcast("Move taken back (" + info.movesRemaining + " moves stand). " + tblColourName(goColourToMove(game)) + " to move.");
      await tblSave();
      tblRenderStatus();
      await botDriveSeatedBots();
    });
  });

  match.onFinalized.add((info) => {
    world.log("Go: the match is " + info.status + (info.ranked ? " (ranked)." : " (unranked)."));
  });
}

void tblRun(async () => {
  if (!(await tblEnsureReady())) return;
  world.log("Go " + GO_N + "x" + GO_N + " ready.");
  await botDriveSeatedBots();
});

